package com.qrid.servlet;
import com.qrid.dao.*;import com.qrid.model.User;import javax.servlet.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.IOException;
@WebServlet(urlPatterns={"/admin/dashboard","/security/dashboard","/staff/dashboard"}) public class DashboardServlet extends HttpServlet{
 protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{User u=(User)r.getSession().getAttribute("user");try{String dept="STAFF".equals(u.getRole())?u.getDepartment():null;r.setAttribute("totalIdentities",AuditDao.count("SELECT COUNT(*) FROM identities"+(dept==null?"":" WHERE department=?"),dept==null?new Object[]{}:new Object[]{dept}));r.setAttribute("activeIdentities",AuditDao.count("SELECT COUNT(*) FROM identities WHERE status='ACTIVE'"+(dept==null?"":" AND department=?"),dept==null?new Object[]{}:new Object[]{dept}));r.setAttribute("todayScans",AuditDao.count("SELECT COUNT(*) FROM scan_logs WHERE DATE(scanned_at)=CURRENT_DATE"));r.setAttribute("suspended",AuditDao.count("SELECT COUNT(*) FROM identities WHERE status='SUSPENDED'"+(dept==null?"":" AND department=?"),dept==null?new Object[]{}:new Object[]{dept}));r.setAttribute("recentScans",new ScanDao().list(7,dept));r.setAttribute("weekly",new ScanDao().weekly());String page="ADMIN".equals(u.getRole())?"admin/dashboard.jsp":"SECURITY".equals(u.getRole())?"security/dashboard.jsp":"staff/dashboard.jsp";r.getRequestDispatcher("/WEB-INF/views/"+page).forward(r,s);}catch(Exception e){throw new ServletException(e);}}
}
